<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>پایگاه معارف استاد حامد رنجبر</title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Vazirmatn:wght@300;400;500;600;700;800&display=swap" rel="stylesheet"><style>
:root{--g:#0f766e;--g2:#14b8a6;--g3:#e9f8f5;--ink:#153735;--muted:#6a7f7c;--bg:#f6fbfa;--line:#dcebe8;--danger:#b42318;--shadow:0 12px 34px rgba(15,118,110,.08)}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);font-family:Vazirmatn,Tahoma,sans-serif}.container{width:min(1180px,calc(100% - 32px));margin:auto}button,input,textarea,select{font:inherit}button{cursor:pointer}.top{position:sticky;top:0;z-index:80;background:#ffffffed;backdrop-filter:blur(14px);border-bottom:1px solid var(--line)}.nav{min-height:72px;display:flex;align-items:center;justify-content:space-between;gap:14px}.brand{border:0;background:none;color:var(--ink);font-size:19px;font-weight:800}.navlinks{display:flex;gap:7px;flex-wrap:wrap}.btn,.navbtn{border:1px solid var(--line);background:#fff;color:var(--ink);border-radius:12px;padding:9px 14px;transition:.18s ease}.btn:hover,.navbtn:hover{transform:translateY(-1px);box-shadow:0 7px 18px rgba(15,118,110,.1)}.btn.primary{background:var(--g);border-color:var(--g);color:#fff}.btn.ghost{background:var(--g3);color:var(--g);border-color:#c9ebe5}.btn.danger{background:#fff5f4;color:var(--danger);border-color:#f5c6c2}.hero{padding:46px 0 24px}.hero h1{font-size:35px;line-height:1.5;margin:0 0 8px}.hero p{margin:0;line-height:2;color:var(--muted)}.quick{display:flex;gap:8px;overflow:auto;padding:8px 0 20px}.quick .navbtn{white-space:nowrap}.section{margin:22px 0 36px}.head{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:15px}.head h2{margin:0;font-size:22px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.grid2{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}.card{background:#fff;border:1px solid var(--line);border-radius:20px;padding:18px;box-shadow:var(--shadow);transition:transform .22s ease,box-shadow .22s ease}.hoverable:hover{transform:scale(1.025);box-shadow:0 18px 42px rgba(15,118,110,.14)}.card h3{margin:0 0 8px;font-size:19px}.meta{display:flex;flex-wrap:wrap;gap:7px;font-size:12px;color:var(--muted);margin:9px 0}.pill,.tag{display:inline-flex;align-items:center;background:#eef9f7;color:var(--g);border-radius:999px;padding:5px 10px;border:1px solid transparent}.tag{border:0;font-size:12px;cursor:pointer;transition:.18s}.tag:hover{background:#d9f5ef;transform:translateY(-1px)}.tags{display:flex;gap:6px;flex-wrap:wrap;margin-top:12px}.audio{width:100%;margin:14px 0}.fish-card{background:#fbfefd;border:1px solid #e1eeeb;border-radius:17px;padding:15px;margin-top:10px;transition:.22s ease}.fish-card:hover{transform:scale(1.015);box-shadow:0 10px 24px rgba(15,118,110,.08)}.fish-title{font-weight:800;margin-bottom:6px}.fish-preview{line-height:2;color:#506562;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}.time{border:0;background:#dcf7f2;color:var(--g);border-radius:8px;padding:4px 8px;font-size:12px;font-weight:800}.fish-actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:10px}.poster{width:100%;max-height:360px;object-fit:cover;border-radius:17px}.album{columns:3 220px;column-gap:12px;margin-top:15px}.album img{width:100%;display:block;margin:0 0 12px;border-radius:16px;cursor:pointer;break-inside:avoid;transition:.2s;box-shadow:0 8px 20px rgba(0,0,0,.07)}.album img:hover{transform:scale(1.01)}.gallery{columns:4 210px;column-gap:12px}.gallery-item{break-inside:avoid;margin:0 0 12px;position:relative}.gallery-item img{width:100%;display:block;border-radius:17px;cursor:pointer;box-shadow:0 8px 22px rgba(0,0,0,.07);transition:.22s}.gallery-item:hover img{transform:scale(1.012);filter:saturate(1.03)}.gallery-cap{position:absolute;right:10px;left:10px;bottom:10px;background:#102f2dcc;color:#fff;padding:7px 10px;border-radius:10px;font-size:11px;opacity:0;transition:.2s}.gallery-item:hover .gallery-cap{opacity:1}.page{background:#fff;border:1px solid var(--line);border-radius:22px;padding:22px;margin:20px 0;box-shadow:var(--shadow)}.article-body,.fish-full{white-space:pre-wrap;line-height:2.25}.adminbar{display:none;background:#eaf8f5;border:1px solid #c6e8e2;border-radius:20px;padding:18px;margin:20px 0}.is-admin .adminbar{display:block}.formgrid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.field{display:flex;flex-direction:column;gap:6px}.field.full{grid-column:1/-1}.field label{font-size:12px;font-weight:800;color:#536a67}.field input,.field textarea,.field select{border:1px solid #d6e5e2;background:#fff;border-radius:12px;padding:11px;outline:none}.field textarea{min-height:120px;resize:vertical}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.empty{text-align:center;color:#82938f;padding:35px}.small{font-size:12px;color:var(--muted)}.modal{position:fixed;inset:0;background:#08201e9c;z-index:200;display:none;align-items:center;justify-content:center;padding:15px}.modal.show{display:flex}.modalbox{width:min(820px,100%);max-height:92vh;overflow:auto;background:#fff;border-radius:23px;padding:22px;box-shadow:0 30px 90px #0004}.modalhead{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:14px}.modalhead h2{margin:0}.close{border:0;background:#f0f4f4;border-radius:10px;padding:7px 11px;font-size:18px}.toast{position:fixed;bottom:20px;left:20px;background:#153735;color:#fff;padding:12px 16px;border-radius:12px;z-index:400;display:none}.calendar{display:none;position:fixed;z-index:320;inset:0;background:#08201e66;align-items:center;justify-content:center;padding:15px}.calendar.show{display:flex}.calbox{background:#fff;width:min(620px,100%);border-radius:22px;padding:20px;box-shadow:0 30px 90px #0004}.wheel-wrap{display:grid;grid-template-columns:1fr 1.5fr 1fr;gap:9px;margin:14px 0}.wheel{height:210px;overflow-y:auto;scroll-snap-type:y mandatory;border:1px solid var(--line);border-radius:16px;padding:72px 0;background:#fbfefd}.wheel button{display:block;width:100%;height:42px;border:0;background:none;scroll-snap-align:center;color:#526a67}.wheel button.active{background:#dff6f2;color:var(--g);font-weight:800}.calhint{text-align:center;color:var(--muted);font-size:12px}.selected-date{background:var(--g3);padding:10px;border-radius:12px;line-height:1.9}.login-note{background:#fff7e8;border:1px solid #f6d79a;border-radius:12px;padding:10px;color:#805b13}.tree-node{padding:10px;background:#f7fbfa;border-radius:12px}.tree-child{margin-right:20px;border-right:2px solid #d6ece8;padding-right:10px;margin-top:7px}.definition{background:#f0fdfa;border-right:4px solid var(--g2);padding:13px;border-radius:12px;line-height:2}.tag-hero{background:linear-gradient(135deg,#0f766e,#159b8f);color:#fff;border-radius:25px;padding:27px;box-shadow:0 20px 50px #0f766e24}.tag-hero .tag{background:#fff;color:var(--g);font-size:15px}.session-seq{display:grid;gap:22px}.session-block{padding:20px;border:1px solid var(--line);border-radius:22px;background:#fff}.session-block:not(:last-child)::after{content:'↓';display:block;text-align:center;font-size:25px;color:var(--g2);margin-top:18px}.footer{margin-top:55px;background:#113633;color:#dcefeb;padding:38px 0}.footer-grid{display:grid;grid-template-columns:2fr 1fr 1fr;gap:25px}.footer a{color:#b8e7df;text-decoration:none}.qr{width:115px;height:115px;background:#fff;border-radius:14px;padding:8px;object-fit:contain}.footer small{color:#a9c7c3}.hidden{display:none!important}@media(max-width:900px){.grid{grid-template-columns:1fr 1fr}.gallery{columns:3 180px}.footer-grid{grid-template-columns:1fr 1fr}}@media(max-width:620px){.container{width:calc(100% - 20px)}.nav{align-items:flex-start;padding:10px 0}.navlinks{display:none}.hero{padding-top:30px}.hero h1{font-size:27px}.grid,.grid2,.formgrid{grid-template-columns:1fr}.gallery{columns:2 140px}.album{columns:2 140px}.footer-grid{grid-template-columns:1fr}.wheel-wrap{grid-template-columns:1fr 1fr 1fr}.wheel{height:190px}}
.fish-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.session-archive{display:grid;grid-template-columns:112px minmax(0,1fr);gap:20px;align-items:start}.year-rail{position:sticky;top:86px;max-height:calc(100vh - 104px);overflow:auto;padding:10px;border:1px solid var(--line);border-radius:14px;background:#fff}.year-list{display:grid;gap:5px}.year-choice{border:1px solid transparent;background:transparent;color:var(--muted);padding:8px 6px;border-radius:8px;transition:background .2s ease,color .2s ease,transform .2s ease}.year-choice:hover{background:#eaf5f3;color:var(--g)}.year-choice.active{background:var(--g);color:#fff;box-shadow:0 5px 14px #0f766e33}.category-filter{display:flex;gap:8px;overflow:auto;padding:4px 0 14px}.category-choice{white-space:nowrap;border:1px solid var(--line);border-radius:999px;background:#fff;padding:8px 13px;color:var(--ink)}.category-choice.active{background:#153735;color:#fff;border-color:#153735}.archive-list{animation:archiveIn .32s ease both}.session-archive-card{border-top:4px solid var(--category-color,#0f766e)}.collection-session-row{display:flex;justify-content:space-between;gap:12px;padding:8px 0;border-bottom:1px solid var(--line)}.collection-session-row:last-child{border-bottom:0}.hoverable{transition:transform .24s cubic-bezier(.2,.7,.2,1),box-shadow .24s ease,border-color .24s ease}.hoverable:hover{transform:translateY(-5px);box-shadow:0 18px 38px rgba(15,55,53,.13);border-color:#9acfc5}@keyframes archiveIn{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}@media(max-width:900px){.fish-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:700px){.session-archive{grid-template-columns:1fr}.year-rail{position:static;max-height:180px}.year-list{grid-template-columns:repeat(4,minmax(0,1fr))}.fish-grid{grid-template-columns:1fr}}
</style></head><body>
<header class="top"><div class="container nav"><button class="brand" onclick="goHome()">پایگاه معارف استاد حامد رنجبر</button><nav class="navlinks"><button class="navbtn" onclick="showHome()">خانه</button><button class="navbtn" onclick="showSessions()">جلسات</button><button class="navbtn" onclick="showArticles()">مطالب</button><button class="navbtn" onclick="showAnnouncements()">اعلانات</button><button class="navbtn" onclick="showGallery()">نگارخانه</button><button class="navbtn" onclick="showTags()">برچسب‌ها</button><button class="navbtn" onclick="showAboutTeacher()">درباره استاد</button><button class="navbtn" onclick="adminAction()">مدیریت</button></nav></div></header>
<main class="container"><section id="app"></section></main>
<footer class="footer"><div class="container footer-grid"><div><h3>پایگاه معارف استاد حامد رنجبر</h3><p id="footerDesc">آرشیو جلسات صوتی، یادداشت‌ها، مطالب و اعلان‌های مراسم.</p><small>این پایگاه با هدف دسترسی منظم و سریع به معارف استاد طراحی شده است.</small></div><div><h4>دسترسی سریع</h4><p><a href="javascript:showSessions()">جلسات</a></p><p><a href="javascript:showArticles()">مطالب</a></p><p><a href="javascript:showGallery()">نگارخانه</a></p><p><a href="javascript:showTags()">برچسب‌ها</a></p><p><a href="javascript:showAboutTeacher()">درباره استاد</a></p></div><div><h4>رسانه‌های اجتماعی</h4><p><a id="baleLink" target="_blank" rel="noopener noreferrer">بله</a></p><p><a id="eitaaLink" target="_blank" rel="noopener noreferrer">ایتا</a></p><div style="display:flex;justify-content:flex-start;margin-top:10px"><img class="qr" id="qr" src="assets/monibin-eitaa-qr.svg" alt="کد QR کانال ایتا"></div></div></div></footer>
<div id="modal" class="modal"><div class="modalbox" id="modalbox"></div></div><div id="calendar" class="calendar"><div class="calbox" id="calbox"></div></div><div id="lightbox" class="modal"><div class="modalbox" style="background:#102f2d;color:#fff;text-align:center"><div class="modalhead"><span id="lightCaption"></span><button class="close" onclick="closeLightbox()">✕</button></div><img id="lightImg" style="max-width:100%;max-height:78vh;border-radius:15px;object-fit:contain"><div class="actions" style="justify-content:center"><button class="btn" onclick="lightPrev()">قبلی</button><button class="btn" onclick="lightNext()">بعدی</button></div></div></div><div id="toast" class="toast"></div>
<script>
const state={};let dateTarget=null,lightItems=[],lightIndex=0;
const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
function api(path,opt={}){const isForm=opt.body instanceof FormData;opt.headers=Object.assign(isForm?{}:{'Content-Type':'application/json'},{'X-CSRF-Token':state.csrf||''},opt.headers||{});return fetch('api/'+path,opt).then(async r=>{const x=await r.json().catch(()=>({}));if(!r.ok){if(r.status===401){toast('نشست مدیر منقضی شده؛ دوباره وارد شوید.');adminLogin();}throw new Error(x.error||'خطا');}return x;})}
async function load(){const x=await fetch('api/data.php').then(r=>r.json());Object.assign(state,x);document.body.classList.toggle('is-admin',!!state.isAdmin);$('footerDesc').textContent=state.settings?.site_description||'';$('baleLink').href=state.settings?.bale_url||'#';$('eitaaLink').href=state.settings?.eitaa_url||'#';showHome();if(state.isAdmin&&state.mustChangePassword)openPasswordChange()}
function goHome(){showHome();window.scrollTo({top:0,behavior:'smooth'})}function showHome(){renderHome()}function renderHome(){let html=`<section class="hero"><h1>پایگاه معارف استاد حامد رنجبر</h1><p>${esc(state.settings?.site_description||'آرشیو منظم جلسات صوتی، یادداشت‌ها، مطالب و اعلان‌های مراسم')}</p></section><div class="quick"><button class="navbtn" onclick="showSessions()">جلسات</button><button class="navbtn" onclick="showAnnouncements()">اعلانات</button><button class="navbtn" onclick="showGallery()">نگارخانه</button><button class="navbtn" onclick="showTags()">برچسب‌ها</button></div>`;
html+=adminPanel();html+=`<section class="section"><div class="head"><h2>اعلانات</h2><button class="btn ghost" onclick="showAnnouncements()">همه اعلانات</button></div><div class="grid">${state.announcements.filter(isAnnouncementActive).map(announcementCard).join('')||'<div class="empty">اعلانی ثبت نشده است.</div>'}</div></section>`;
html+=`<section class="section"><div class="head"><h2>آخرین جلسات</h2><button class="btn ghost" onclick="showSessions()">همه جلسات</button></div><div class="grid">${state.lectures.slice(0,6).map(sessionCard).join('')||'<div class="empty">هنوز جلسه‌ای ثبت نشده است.</div>'}</div></section>`;
html+=`<section class="section"><div class="head"><h2>جدیدترین مطالب</h2><button class="btn ghost" onclick="showArticles()">همه مطالب</button></div><div class="grid">${state.articles.slice(0,3).map(articleCard).join('')||'<div class="empty">مطلبی ثبت نشده است.</div>'}</div></section>`;$('app').innerHTML=html}
function adminPanel(){if(!state.adminSignedIn)return'';if(state.adminRole==='editor')return `<section class="adminbar"><div class="head"><h2>حساب ویراستار</h2><button class="btn danger" onclick="logout()">خروج</button></div><p class="small">دسترسی این حساب فقط‌خواندنی است.</p></section>`;return `<section class="adminbar"><div class="head"><h2>مدیریت محتوا</h2><button class="btn danger" onclick="logout()">خروج</button></div><div class="actions"><button class="btn primary" onclick="openLecture()">+ جلسه صوتی</button><button class="btn" onclick="openArticle()">+ مطلب</button><button class="btn" onclick="openAnnouncement()">+ اعلان</button><button class="btn" onclick="openTag()">+ برچسب</button><button class="btn" onclick="openCategories()">دسته‌بندی‌ها</button><button class="btn" onclick="openCollectionManager()">مجموعه‌ها</button>${state.adminRole==='owner'?'<button class="btn" onclick="manageAdmins()">مدیران و نقش‌ها</button><button class="btn" onclick="editAboutTeacher()">ویرایش درباره استاد</button>':''}</div><div class="small" style="margin-top:9px">ثبت جلسه در حالت عادی «تک جلسه» است؛ برای مجموعه، مجموعه و بازه تاریخ را انتخاب کنید. افزودن جلسه بعدی به همان مجموعه هم از صفحه جلسه انجام می‌شود.</div></section>`}
function sessionCard(l){return `<article class="card hoverable"><div class="meta"><span class="pill">${esc(l.category||'جلسه')}</span>${l.collection_title?`<span class="pill">${esc(l.collection_title)}</span>`:''}</div><h3>${esc(l.title)}</h3><div class="meta"><span>تاریخ: ${esc(l.session_date)}</span>${sessionHijri(l)?`<span>قمری: ${esc(sessionHijri(l))}</span>`:''}</div><p class="small">${esc(l.description||'')}</p><audio class="audio" controls preload="none" src="${esc(l.audio_url)}"></audio>${renderTags(l.tags)}<div class="actions"><button class="btn primary" onclick="openLecturePage(${l.id})">مطالعه جلسه</button>${state.isAdmin?`<button class="btn" onclick="openLecture(${l.id})">ویرایش</button><button class="btn danger" onclick="del('lectures.php',${l.id})">حذف</button>`:''}</div></article>`}
function announcementRangeLabel(a){return a.start_jalali&&a.end_jalali?`${a.start_jalali} تا ${a.end_jalali}`:(a.event_date||'')}
function currentGregorianDate(){const today=new Date();return gregDateStr([today.getFullYear(),today.getMonth()+1,today.getDate()])}
function isAnnouncementActive(a){const today=currentGregorianDate();return(!a.start_date_gregorian||a.start_date_gregorian<=today)&&(!a.end_date_gregorian||a.end_date_gregorian>=today)}
function isAnnouncementExpired(a){return !!a.end_date_gregorian&&a.end_date_gregorian<currentGregorianDate()}
function announcementCard(a){return `<article class="card hoverable"><div class="meta"><span class="pill">اعلان مراسم</span>${state.isAdmin&&isAnnouncementExpired(a)?'<span class="pill">بایگانی‌شده</span>':''}</div>${a.poster_url?`<img class="poster" src="${esc(a.poster_url)}">`:''}<h3>${esc(a.title)}</h3><div class="meta"><span>${esc(announcementRangeLabel(a))}</span>${a.event_time?`<span>${esc(a.event_time)}</span>`:''}${a.location?`<span>${esc(a.location)}</span>`:''}</div><p class="small">${esc(a.body)}</p>${renderTags(a.tags)}<div class="actions"><button class="btn primary" onclick="openAnnouncementPage(${a.id})">مشاهده</button>${state.isAdmin?`<button class="btn" onclick="openAnnouncement(${a.id})">ویرایش</button><button class="btn danger" onclick="del('announcements.php',${a.id})">حذف</button>`:''}</div></article>`}
function articleCard(a){return `<article class="card hoverable"><div class="meta"><span class="pill">مطلب</span>${a.category?`<span>${esc(a.category)}</span>`:''}</div><h3>${esc(a.title)}</h3><div class="meta">${a.article_date?`<span>${esc(a.article_date)}</span>`:''}${a.author?`<span>${esc(a.author)}</span>`:''}</div><p class="small">${esc(a.body.slice(0,180))}${a.body.length>180?'…':''}</p>${renderTags(a.tags)}<div class="actions"><button class="btn primary" onclick="openArticlePage(${a.id})">مطالعه مطلب</button>${state.isAdmin?`<button class="btn" onclick="openArticle(${a.id})">ویرایش</button><button class="btn danger" onclick="del('articles.php',${a.id})">حذف</button>`:''}</div></article>`}
function renderTags(tags=[]){return `<div class="tags">${tags.map(t=>`<button class="tag" data-tag="${esc(t)}" onclick="showTag(this.dataset.tag)">#${esc(t)}</button>`).join('')}</div>`}
document.addEventListener('click',e=>{const tag=e.target.closest('.tag');if(!tag)return;const name=tag.dataset.tag||tag.textContent.replace(/^#/,'').trim();if(!name)return;e.preventDefault();e.stopImmediatePropagation();showTag(name)},true);
function lectureJalaliYear(lecture){const date=lecture.session_date_gregorian||jalaliInputToGreg(lecture.session_date||'');if(!date)return 1380;const [year,month,day]=date.split('-').map(Number);return g2j(year,month,day)[0]}
function sessionColor(name){const palette=['#0f766e','#a34b31','#276678','#8a5a16','#765548'];let hash=0;for(const char of String(name||''))hash=(hash*31+char.charCodeAt(0))|0;return palette[Math.abs(hash)%palette.length]}
function archiveSessionCard(lecture){return `<article class="card hoverable session-archive-card" style="--category-color:${sessionColor(lecture.category)}"><div class="meta"><span class="pill">${esc(lecture.category||'جلسه')}</span></div><h3>${esc(lecture.title)}</h3><div class="meta"><span>${esc(lecture.session_date)}</span>${lecture.hijri_date?`<span>${esc(lecture.hijri_date)}</span>`:''}</div><div class="actions"><button class="btn primary" onclick="openLecturePage(${lecture.id})">مشاهده جلسه</button>${state.isAdmin?`<button class="btn" onclick="openLecture(${lecture.id})">ویرایش</button>`:''}</div></article>`}
function archiveCollectionCard(collectionId,lectures){const first=lectures[0],collection=state.collections.find(item=>Number(item.id)===Number(collectionId));const title=collection?.title||first.collection_title||first.title;const plannedCount=Number(collection?.session_count||first.session_count||lectures.length);const dates=lectures.map(item=>item.session_date).filter(Boolean);return `<article class="card hoverable session-archive-card" style="--category-color:${sessionColor(first.category)}"><div class="meta"><span class="pill">${esc(first.category||'مجموعه جلسات')}</span><span class="pill">${faNum(plannedCount)} جلسه در مجموعه</span></div><h3>${esc(title)}</h3>${dates.length?`<div class="meta"><span>${esc(dates[0])} تا ${esc(dates[dates.length-1])}</span></div>`:''}<div>${lectures.map(item=>`<div class="collection-session-row"><span>${item.session_number?`جلسه ${faNum(item.session_number)} · `:''}${esc(item.session_date||'')}</span>${state.isAdmin?`<button class="btn" onclick="openLecture(${item.id})">ویرایش</button>`:''}</div>`).join('')}</div><div class="actions"><button class="btn primary" onclick="openLecturePage(${first.id})">مشاهده مجموعه</button></div></article>`}
let selectedSessionYear=0,selectedSessionCategory=0;
function showSessions(year=null,category=null){const now=new Date(),currentYear=g2j(now.getFullYear(),now.getMonth()+1,now.getDate())[0];if(!selectedSessionYear)selectedSessionYear=currentYear;if(year!==null)selectedSessionYear=Number(year);if(category!==null)selectedSessionCategory=Number(category);const categories=['منبر محرم','تفسیر قرآن','منبر فاطمیه','درس','بیان احکام'].map(name=>state.categories.find(item=>item.name===name&&item.kind==='audio')).filter(Boolean);const years=Array.from({length:Math.max(0,currentYear-1380)+1},(_,index)=>currentYear-index);const matches=state.lectures.filter(item=>lectureJalaliYear(item)===selectedSessionYear&&(!selectedSessionCategory||Number(item.category_id)===selectedSessionCategory));const groups=[],seen=new Set();for(const lecture of matches){if(lecture.collection_id){const key=`collection-${lecture.collection_id}`;if(seen.has(key))continue;seen.add(key);groups.push({collectionId:lecture.collection_id,lectures:matches.filter(item=>Number(item.collection_id)===Number(lecture.collection_id)).sort((a,b)=>(a.session_date_gregorian||'').localeCompare(b.session_date_gregorian||''))})}else groups.push({lecture})}const cards=groups.map(group=>group.collectionId?archiveCollectionCard(group.collectionId,group.lectures):archiveSessionCard(group.lecture)).join('');$('app').innerHTML=`<section class="section"><div class="head"><h2>جلسات</h2>${state.isAdmin?`<button class="btn primary" onclick="openLecture()">+ جلسه جدید</button>`:''}</div><div class="category-filter"><button class="category-choice ${selectedSessionCategory?'':'active'}" onclick="showSessions(${selectedSessionYear},0)">همه انواع</button>${categories.map(item=>`<button class="category-choice ${selectedSessionCategory===Number(item.id)?'active':''}" onclick="showSessions(${selectedSessionYear},${item.id})">${esc(item.name)}</button>`).join('')}</div><div class="small" style="margin-bottom:15px">جلسه‌ها بر اساس تاریخ برگزاری مرتب شده‌اند؛ سال‌های قابل انتخاب از ۱۳۸۰ به بعد هستند.</div><div class="session-archive"><aside class="year-rail"><div class="small" style="margin-bottom:8px">سال</div><div class="year-list">${years.map(item=>`<button class="year-choice ${selectedSessionYear===item?'active':''}" onclick="showSessions(${item},${selectedSessionCategory})">${faNum(item)}</button>`).join('')}</div></aside><div class="grid archive-list">${cards||'<div class="empty">در این سال و دسته جلسه‌ای ثبت نشده است.</div>'}</div></div></section>`}
function showArticles(){ $('app').innerHTML=`<section class="section"><div class="head"><h2>مطالب</h2>${state.isAdmin?`<button class="btn primary" onclick="openArticle()">+ مطلب جدید</button>`:''}</div><div class="grid">${state.articles.map(articleCard).join('')||'<div class="empty">مطلبی ثبت نشده است.</div>'}</div></section>`}
function showAnnouncements(){ $('app').innerHTML=`<section class="section"><div class="head"><h2>اعلانات مراسم</h2>${state.isAdmin?`<button class="btn primary" onclick="openAnnouncement()">+ اعلان جدید</button>`:''}</div><div class="grid">${state.announcements.map(announcementCard).join('')||'<div class="empty">اعلانی ثبت نشده است.</div>'}</div></section>`}
function showGallery(){const arr=state.gallery||[];$('app').innerHTML=`<section class="section"><div class="head"><h2>نگارخانه</h2><span class="small">پوستر اعلانات و عکس‌های جلسات در یک آرشیو</span></div><div class="gallery">${arr.map((p,i)=>`<div class="gallery-item"><img src="${esc(p.url)}" alt="" loading="lazy" onclick="openLightbox(${i})"><div class="gallery-cap">${esc(p.caption||p.lecture_title||'')}</div></div>`).join('')||'<div class="empty">هنوز عکسی در نگارخانه نیست.</div>'}</div></section>`;lightItems=arr;lightIndex=0}
function showTags(){const tags=state.tags||[];$('app').innerHTML=`<section class="section"><div class="head"><h2>برچسب‌ها</h2>${state.isAdmin?`<button class="btn primary" onclick="openTag()">+ برچسب جدید</button>`:''}</div><div class="grid">${tags.map(t=>`<article class="card hoverable" data-tag="${esc(t.name)}" onclick="showTag(this.dataset.tag)" style="cursor:pointer"><div class="meta"><span class="pill">برچسب</span></div><h3>#${esc(t.name)}</h3>${t.definition?`<p class="small">${esc(t.definition)}</p>`:''}${state.isAdmin?`<button class="btn" onclick="event.stopPropagation();openTag(${t.id})">ویرایش</button>`:''}</article>`).join('')||'<div class="empty">برچسبی نیست.</div>'}</div></section>`}
function tagUsage(name){let n=0;n+=state.lectures.filter(x=>x.tags.includes(name)).length;n+=state.articles.filter(x=>x.tags.includes(name)).length;n+=state.announcements.filter(x=>x.tags.includes(name)).length;state.lectures.forEach(l=>l.fishes.forEach(f=>{if(f.tags.includes(name))n++}));return n}
function showTag(name){const t=state.tags.find(x=>x.name===name)||{};const parent=t.parent_id?state.tags.find(x=>Number(x.id)===Number(t.parent_id)):null;const children=state.tags.filter(x=>Number(x.parent_id)===Number(t.id));const lectures=state.lectures.filter(x=>x.tags.includes(name));const articles=state.articles.filter(x=>x.tags.includes(name));const anns=state.announcements.filter(x=>x.tags.includes(name));const fishes=[];state.lectures.forEach(l=>l.fishes.forEach(f=>{if(f.tags.includes(name))fishes.push({...f,lecture:l})}));const related=[...new Set([...lectures,...articles,...anns,...fishes.map(x=>x.f)].flatMap(x=>x.tags||[]).filter(x=>x!==name))];$('app').innerHTML=`<section class="section"><div class="tag-hero"><div class="small" style="color:#c5eee8">صفحه برچسب</div><h1 style="margin:4px 0 8px">#${esc(name)}</h1>${t.definition?`<p style="line-height:2;margin:0">${esc(t.definition)}</p>`:''}<div class="meta" style="color:#d8f3ef"><span>تعداد موارد: ${tagUsage(name)}</span>${parent?`<span>والد: #${esc(parent.name)}</span>`:''}</div><div class="tags" style="margin-top:14px">${children.map(c=>`<button class="tag" onclick="showTag(${JSON.stringify(c.name)})">#${esc(c.name)}</button>`).join('')}</div></div></section><section class="section"><div class="head"><h2>برچسب‌های مرتبط</h2></div><div class="tags" style="margin-bottom:22px">${related.map(x=>`<button class="tag" onclick="showTag(${JSON.stringify(x)})">#${esc(x)}</button>`).join('')||'<span class="small">برچسب مرتبطی ثبت نشده است.</span>'}</div></section><section class="section"><div class="head"><h2>جلسات مرتبط</h2></div><div class="grid">${lectures.map(sessionCard).join('')||'<div class="empty">جلسه‌ای مرتبط نیست.</div>'}</div></section><section class="section"><div class="head"><h2>یادداشت‌های مرتبط</h2></div><div class="grid">${fishes.map(x=>fishSmall(x.f,x.lecture)).join('')||'<div class="empty">یادداشتی مرتبط نیست.</div>'}</div></section><section class="section"><div class="head"><h2>مطالب مرتبط</h2></div><div class="grid">${articles.map(articleCard).join('')||'<div class="empty">مطلب مرتبطی نیست.</div>'}</div></section><section class="section"><div class="head"><h2>اعلانات مرتبط</h2></div><div class="grid">${anns.map(announcementCard).join('')||'<div class="empty">اعلانی مرتبط نیست.</div>'}</div></section>`}
function fishSmall(f,l){return `<article class="card hoverable"><div class="meta"><span class="pill">${esc(l.title)}</span><button class="time" onclick="playAt(${l.id},${f.timestamp_seconds})">${formatTime(f.timestamp_seconds)}</button></div>${f.title?`<div class="fish-title">${esc(f.title)}</div>`:''}<div class="fish-preview">${esc(f.body.replace(/\[\[.*?\]\]/g,'').slice(0,180))}</div><div class="actions"><button class="btn primary" onclick="openFishPage(${f.id},${l.id})">مطالعه کامل</button>${state.isAdmin?`<button class="btn" onclick="openFish(${l.id},${f.id})">ویرایش</button><button class="btn danger" onclick="del('fishes.php',${f.id})">حذف</button>`:''}</div></article>`}
function openLecturePage(id){const l=state.lectures.find(x=>Number(x.id)===Number(id));if(!l)return;const seq=l.collection_id?state.lectures.filter(x=>Number(x.collection_id)===Number(l.collection_id)).sort((a,b)=>(a.session_date_gregorian||'').localeCompare(b.session_date_gregorian||'')): [l];$('app').innerHTML=`<section class="section"><button class="btn ghost" onclick="showSessions()">← بازگشت به جلسات</button><div class="session-seq" style="margin-top:15px">${seq.map(renderSessionBlock).join('')}</div></section>`;window.scrollTo({top:0,behavior:'smooth'})}
function renderSessionBlock(l){const first=l.fishes.slice(0,3),hijri=sessionHijri(l);return `<article class="session-block"><div class="meta"><span class="pill">${esc(l.collection_title||'جلسه')}</span>${l.session_number?`<span>شماره جلسه: ${faNum(l.session_number)}${l.session_count?` از ${faNum(l.session_count)}`:''}</span>`:''}<span>تاریخ شمسی: ${esc(l.session_date)}</span>${hijri?`<span>تاریخ قمری: ${esc(hijri)}</span>`:''}</div><h2>${esc(l.title)}</h2><p class="small">${esc(l.description||'')}</p><audio class="audio" controls preload="metadata" src="${esc(l.audio_url)}"></audio>${renderAlbum(l)}<div class="head" style="margin-top:18px"><h3>یادداشت‌های جلسه</h3></div><div class="fish-grid">${first.map(f=>fishSmall(f,l)).join('')||'<div class="empty">برای این جلسه هنوز یادداشتی ثبت نشده است.</div>'}</div>${l.fishes.length>3?`<div class="actions"><button class="btn primary" onclick="showFishList(${l.id})">سایر یادداشت‌های این جلسه</button></div>`:''}${state.isAdmin?`<div class="actions"><button class="btn" onclick="openLecture(${l.id})">ویرایش این جلسه</button>${l.collection_id?`<button class="btn primary" onclick="openLecture(0,${l.collection_id})">+ افزودن جلسه جدید به این مجموعه</button>`:''}</div>`:''}</article>`}
function renderAlbum(l){if(!l.photos?.length)return'';return `<div class="album">${l.photos.map((p,i)=>`<img src="${esc(p.url)}" alt="${esc(p.caption||'')}" onclick='openLocalLight(${JSON.stringify(l.photos)},${i})'>`).join('')}</div>`}
function openLocalLight(items,i){lightItems=items;lightIndex=i;openLightbox(i)}
function showFishList(lid){const l=state.lectures.find(x=>Number(x.id)===Number(lid));if(!l)return;$('app').innerHTML=`<section class="section"><button class="btn ghost" onclick="openLecturePage(${l.id})">← بازگشت</button><div class="page"><h1>سایر یادداشت‌های ${esc(l.title)}</h1><div class="fish-grid">${l.fishes.map(f=>fishSmall(f,l)).join('')}</div></div></section>`}
function openFishPage(fid,lid){const l=state.lectures.find(x=>Number(x.id)===Number(lid));const f=l?.fishes.find(x=>Number(x.id)===Number(fid));if(!f)return;modal(`<div class="modalhead"><h2>${f.title?esc(f.title):'یادداشت'}</h2><button class="close" onclick="closeModal()">✕</button></div><div class="meta"><span class="pill">${esc(l.title)}</span><button class="time" onclick="playAt(${l.id},${f.timestamp_seconds})">پخش از ${formatTime(f.timestamp_seconds)}</button></div><div class="fish-full">${renderLinkedText(f.body)}</div><div class="actions"><button class="btn" onclick="closeModal()">بستن</button>${state.isAdmin?`<button class="btn" onclick="closeModal();openFish(${l.id},${f.id})">ویرایش</button>`:''}</div>`)}
function renderLinkedText(text){return esc(text).replace(/\[\[article:(\d+)\|([^\]]+)\]\]/g,(m,id,label)=>`<button class="btn ghost" onclick="closeModal();openArticlePage(${id})">${esc(label)}</button>`).replace(/\[\[fish:(\d+):(\d+)\|([^\]]+)\]\]/g,(m,lid,fid,label)=>`<button class="btn ghost" onclick="closeModal();openFishPage(${fid},${lid})">${esc(label)}</button>`)}
function playAt(lid,sec){const l=state.lectures.find(x=>Number(x.id)===Number(lid));if(!l)return;openLecturePage(lid);setTimeout(()=>{const a=document.querySelector('.session-block audio');if(a){a.currentTime=sec;a.play().catch(()=>{})}},150)}
function openArticlePage(id){const a=state.articles.find(x=>Number(x.id)===Number(id));if(!a)return;modal(`<div class="modalhead"><h2>${esc(a.title)}</h2><button class="close" onclick="closeModal()">✕</button></div><div class="meta"><span>شمسی: ${esc(a.article_date||'')}</span>${a.hijri_date?`<span>قمری: ${esc(a.hijri_date)}</span>`:''}<span>${esc(a.author||'')}</span></div>${renderTags(a.tags)}<div class="article-body">${renderLinkedText(a.body)}</div><div class="actions"><button class="btn" onclick="closeModal()">بستن</button>${state.isAdmin?`<button class="btn" onclick="closeModal();openArticle(${a.id})">ویرایش</button>`:''}</div>`)}
function openAnnouncementPage(id){const a=state.announcements.find(x=>Number(x.id)===Number(id));if(!a)return;modal(`<div class="modalhead"><h2>${esc(a.title)}</h2><button class="close" onclick="closeModal()">✕</button></div>${a.poster_url?`<img class="poster" src="${esc(a.poster_url)}">`:''}<div class="meta"><span>بازه شمسی: ${esc(announcementRangeLabel(a))}</span>${a.hijri_date?`<span>قمری: ${esc(a.hijri_date)}</span>`:''}<span>${esc(a.event_time||'')}</span><span>${esc(a.location||'')}</span></div>${renderTags(a.tags)}<div class="article-body">${esc(a.body)}</div><div class="actions"><button class="btn" onclick="closeModal()">بستن</button>${state.isAdmin?`<button class="btn" onclick="closeModal();openAnnouncement(${a.id})">ویرایش</button>`:''}</div>`)}
function modal(html){$('modalbox').innerHTML=html;$('modal').classList.add('show')}function closeModal(){if(state.mustChangePassword)return;$('modal').classList.remove('show');$('modalbox').innerHTML=''}$('modal').addEventListener('click',e=>{if(e.target.id==='modal')closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();closeCalendar();closeLightbox()}});
function toast(t){$('toast').textContent=t;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',3000)}
async function adminAction(){if(state.adminSignedIn){showHome();window.scrollTo({top:0,behavior:'smooth'})}else adminLogin()}
function adminLogin(){modal(`<div class="modalhead"><h2>ورود مدیر</h2><button class="close" onclick="closeModal()">✕</button></div><div class="field"><label>نام کاربری</label><input id="loginUser" autocomplete="username"></div><div class="field" style="margin-top:10px"><label>رمز عبور</label><input id="loginPass" type="password" autocomplete="current-password"></div><div class="actions"><button class="btn primary" onclick="login()">ورود</button></div>`)}
function openPasswordChange(){modal(`<div class="modalhead"><h2>تغییر رمز مدیر</h2></div><p class="small">برای ادامه‌ی مدیریت، رمز پیش‌فرض را با یک رمز شخصی عوض کنید.</p><div class="field"><label>رمز فعلی</label><input id="currentPassword" type="password" autocomplete="current-password"></div><div class="field" style="margin-top:10px"><label>رمز جدید (حداقل ۱۲ نویسه)</label><input id="newPassword" type="password" autocomplete="new-password"></div><div class="field" style="margin-top:10px"><label>تکرار رمز جدید</label><input id="repeatPassword" type="password" autocomplete="new-password"></div><div class="actions"><button class="btn" onclick="logout()">خروج</button><button class="btn primary" onclick="savePasswordChange()">ثبت رمز جدید</button></div>`)}
async function savePasswordChange(){const password=$('newPassword').value;if(password!==$('repeatPassword').value)return toast('تکرار رمز جدید یکسان نیست.');try{await api('auth.php',{method:'POST',body:JSON.stringify({action:'change_password',current_password:$('currentPassword').value,new_password:password})});state.mustChangePassword=false;closeModal();await load();toast('رمز مدیر با موفقیت تغییر کرد.')}catch(error){toast(error.message)}}
async function login(){try{const x=await api('auth.php',{method:'POST',body:JSON.stringify({action:'login',username:$('loginUser').value,password:$('loginPass').value})});state.isAdmin=true;state.csrf=x.csrfToken;closeModal();await load();toast('ورود موفق بود.')}catch(e){toast(e.message)}}
async function logout(){try{await api('auth.php',{method:'POST',body:JSON.stringify({action:'logout'})});state.isAdmin=false;state.mustChangePassword=false;state.csrf='';closeModal();await load()}catch(e){toast(e.message)}}
function catOptions(kind,val){let categories=state.categories.filter(category=>category.kind==='all'||category.kind===kind);if(kind==='audio'){const order=['منبر محرم','تفسیر قرآن','منبر فاطمیه','درس','بیان احکام'];categories=categories.filter(category=>order.includes(category.name)||Number(category.id)===Number(val));categories.sort((left,right)=>order.indexOf(left.name)-order.indexOf(right.name))}return categories.map(category=>`<option value="${category.id}" ${Number(category.id)===Number(val)?'selected':''}>${esc(category.name)}</option>`).join('')}
function tagInput(tags=[]){return `<div class="field full"><label>برچسب‌ها</label><input id="mTags" value="${esc(tags.join('، '))}" placeholder="مثلاً اخلاق، خشوع، نماز"></div>`}
function openLecture(id=0,existingCollection=0){const l=state.lectures.find(x=>Number(x.id)===Number(id))||{};const isEdit=!!id;const col=existingCollection||l.collection_id||0;const c=state.collections.find(x=>Number(x.id)===Number(col))||{};modal(`<div class="modalhead"><h2>${isEdit?'ویرایش جلسه':'ثبت جلسه صوتی'}</h2><button class="close" onclick="closeModal()">✕</button></div><div class="field"><label>نوع بارگذاری</label><div class="actions"><label><input type="radio" name="mode" value="single" ${!col?'checked':''} onchange="toggleLectureMode()"> تک جلسه</label><label><input type="radio" name="mode" value="collection" ${col?'checked':''} onchange="toggleLectureMode()"> مجموعه جلسات</label></div></div><div class="formgrid"><div class="field"><label>عنوان جلسه</label><input id="mTitle" value="${esc(l.title||'')}" placeholder="مثلاً جلسه پنجم محرم"></div><div class="field"><label>دسته</label><select id="mCat">${catOptions('audio',l.category_id)}</select></div><div class="field"><label>تاریخ شمسی</label><input id="mDate" readonly value="${esc(l.session_date||'')}" data-greg="${esc(l.session_date_gregorian||'')}" data-hijri="${esc(l.hijri_date||'')}" onclick="openDatePicker('mDate')" placeholder="انتخاب تاریخ"><div id="mDatePreview" class="selected-date small">${l.session_date?`قمری: ${esc(l.hijri_date||'—')}`:'برای انتخاب تاریخ کلیک کنید'}</div></div><div class="field"><label>فایل صوتی ${isEdit?'(در صورت تغییر انتخاب کنید)':''}</label><input id="mAudio" type="file" accept="audio/*"></div><div class="field"><label>تعداد/شماره جلسه</label><input id="mNum" type="number" min="1" value="${esc(l.session_number||'')}" placeholder="مثلاً 5"></div><div class="field"><label>تعداد کل جلسات</label><input id="mCount" type="number" min="1" value="${esc(l.session_count||'')}" placeholder="مثلاً 10"></div><div id="collectionFields" class="field full ${col?'':'hidden'}"><label>مجموعه جلسات</label><select id="mCollection"><option value="0">مجموعه جدید</option>${state.collections.map(x=>`<option value="${x.id}" ${Number(x.id)===Number(col)?'selected':''}>${esc(x.title)}</option>`).join('')}</select><div id="newCollectionBox" class="formgrid" style="margin-top:10px"><div class="field"><label>عنوان مجموعه</label><input id="mCollectionTitle" value="${esc(c.title||'')}" placeholder="مثلاً دهه محرم ۱۴۰۴"></div><div class="field"><label>تاریخ شروع بازه</label><input id="mStart" readonly value="${esc(c.start_jalali||'')}" data-greg="${esc(c.start_date_gregorian||'')}" onclick="openDatePicker('mStart')"></div><div class="field"><label>تاریخ پایان بازه</label><input id="mEnd" readonly value="${esc(c.end_jalali||'')}" data-greg="${esc(c.end_date_gregorian||'')}" onclick="openDatePicker('mEnd')"></div></div></div>${tagInput(l.tags||[])}<div class="field full"><label>توضیحات</label><textarea id="mDesc">${esc(l.description||'')}</textarea></div><div class="field full"><label>آلبوم عکس جلسه ${isEdit?'(تصاویر جدید را اضافه کنید)':''}</label><input id="mPhotos" type="file" accept="image/*" multiple><div class="small">چند عکس را همزمان انتخاب کنید؛ تصاویر قبلی حذف نمی‌شوند.</div></div></div><div class="actions"><button class="btn" onclick="closeModal()">انصراف</button><button class="btn primary" onclick="saveLecture(${id},${col})">ذخیره جلسه</button></div>`);toggleLectureMode()}
function toggleLectureMode(){const mode=document.querySelector('input[name=mode]:checked')?.value; $('collectionFields').classList.toggle('hidden',mode!=='collection');}
async function uploadFile(type,file){if(!file)return'';const fd=new FormData();fd.append('type',type);fd.append('file',file);const x=await api('upload.php',{method:'POST',headers:{'X-CSRF-Token':state.csrf},body:fd});return x.url}
async function saveLecture(id,oldCol){try{const mode=document.querySelector('input[name=mode]:checked')?.value||'single';let collectionId=oldCol||0;if(mode==='collection'){const selected=Number($('mCollection').value||0);if(selected)collectionId=selected;else{const c=await api('collections.php',{method:'POST',body:JSON.stringify({title:$('mCollectionTitle').value,description:'',start_gregorian:$('mStart').dataset.greg||'',end_gregorian:$('mEnd').dataset.greg||'',start_jalali:$('mStart').value,end_jalali:$('mEnd').value,tags:[]})});collectionId=c.id}}let audio='';if($('mAudio').files[0])audio=await uploadFile('audio',$('mAudio').files[0]);const payload={id,title:$('mTitle').value,category_id:$('mCat').value,date:$('mDate').value,date_gregorian:$('mDate').dataset.greg||'',hijri_date:$('mDate').dataset.hijri||'',description:$('mDesc').value,timestamp:0,audio_url:audio,collection_id:collectionId,session_number:$('mNum').value,session_count:$('mCount').value,tags:$('mTags').value};const saved=await api('lectures.php',{method:id?'PUT':'POST',body:JSON.stringify(payload)});const savedId=id||saved.id;if(id&&collectionId&&mode==='collection')await api('collections.php',{method:'PUT',body:JSON.stringify({id:collectionId,title:$('mCollectionTitle')?.value||state.collections.find(x=>Number(x.id)===collectionId)?.title,description:state.collections.find(x=>Number(x.id)===collectionId)?.description||'',start_gregorian:$('mStart')?.dataset.greg||'',end_gregorian:$('mEnd')?.dataset.greg||'',start_jalali:$('mStart')?.value||'',end_jalali:$('mEnd')?.value||'',lecture_ids:state.collections.find(x=>Number(x.id)===collectionId)?.lecture_ids||[],tags:state.collections.find(x=>Number(x.id)===collectionId)?.tags||[]})});const lid=savedId;const photos=[...$('mPhotos').files];for(let i=0;i<photos.length;i++){const url=await uploadFile('gallery',photos[i]);await api('gallery.php',{method:'POST',body:JSON.stringify({lecture_id:lid,url,caption:'' ,sort_order:i})})}closeModal();await load();toast('جلسه با موفقیت ذخیره شد.')}catch(e){toast(e.message)}}
function openFish(lid,id=0){const l=state.lectures.find(x=>Number(x.id)===Number(lid));const f=l?.fishes.find(x=>Number(x.id)===Number(id))||{};modal(`<div class="modalhead"><h2>${id?'ویرایش یادداشت':'یادداشت جدید'}</h2><button class="close" onclick="closeModal()">✕</button></div><div class="formgrid"><div class="field"><label>عنوان یادداشت (اختیاری)</label><input id="mTitle" value="${esc(f.title||'')}"></div><div class="field"><label>زمان اتصال به جلسه</label><input id="mTime" value="${formatTime(f.timestamp_seconds||0)}" placeholder="مثلاً 4:26 یا 04-26"><div class="small">برای جلسه پنجم یک مجموعه هم همین زمان به همان جلسه متصل می‌شود؛ مثلاً جلسه ۵ → 04:26.</div></div>${tagInput(f.tags||[])}<div class="field full"><label>متن یادداشت</label><textarea id="mBody">${esc(f.body||'')}</textarea></div><div class="field full"><label>اتصال به مطلب یا یادداشت دیگر</label><select id="mLinkType" onchange="refreshLinkTargets()"><option value="article">مطلب</option><option value="fish">یادداشت</option></select><input id="mLinkSearch" oninput="refreshLinkTargets()" placeholder="جست‌وجوی مقصد"><select id="mLinkTarget"></select><input id="mLinkLabel" placeholder="متن لینک"><button class="btn ghost" type="button" onclick="insertFishInternalLink()">درج لینک در متن</button></div></div><div class="actions"><button class="btn" onclick="closeModal()">انصراف</button><button class="btn primary" onclick="saveFish(${lid},${id})">ذخیره</button></div>`);refreshLinkTargets()}
function refreshLinkTargets(){const type=$('mLinkType')?.value||'article',q=($('mLinkSearch')?.value||'').toLowerCase(),sel=$('mLinkTarget');if(!sel)return;let rows=type==='article'?state.articles.map(a=>({v:`article:${a.id}`,t:'مطلب: '+a.title,h:(a.title+' '+a.body).toLowerCase()})):state.lectures.flatMap(l=>l.fishes.map(f=>({v:`fish:${l.id}:${f.id}`,t:'یادداشت: '+(f.title||f.body.slice(0,50))+' — '+l.title,h:(l.title+' '+f.title+' '+f.body).toLowerCase()})));rows=rows.filter(x=>!q||x.h.includes(q)).slice(0,100);sel.innerHTML=rows.map(x=>`<option value="${x.v}">${esc(x.t)}</option>`).join('')||'<option value="">موردی پیدا نشد</option>'}
function insertFishInternalLink(){const t=$('mLinkTarget')?.value,l=($('mLinkLabel')?.value||'').trim(),ta=$('mBody');if(!t||!l)return toast('مقصد و متن لینک را مشخص کنید.');const token=`[[${t}|${l}]]`,s=ta.selectionStart,e=ta.selectionEnd;ta.value=ta.value.slice(0,s)+token+ta.value.slice(e);ta.focus();ta.selectionStart=ta.selectionEnd=s+token.length}
