function openAnnouncement(id=0){const a=state.announcements.find(x=>Number(x.id)===Number(id))||{};const startJalali=a.start_jalali||a.event_date||'';modal(`<div class="modalhead"><h2>${id?'ویرایش اعلان':'اعلان مراسم جدید'}</h2><button class="close" onclick="closeModal()">✕</button></div><div class="formgrid"><div class="field"><label>عنوان</label><input id="mTitle" value="${esc(a.title||'')}"></div><div class="field"><label>دسته</label><select id="mCat">${catOptions('announcement',a.category_id)}</select></div><div class="field"><label>از تاریخ شمسی</label><input id="mStart" readonly value="${esc(startJalali)}" data-greg="${esc(a.start_date_gregorian||jalaliInputToGreg(startJalali))}" data-hijri="${esc(a.hijri_date||'')}" onclick="openDatePicker('mStart')"><div id="mStartPreview" class="selected-date small">شروع بازه نمایش اعلان</div></div><div class="field"><label>تا تاریخ شمسی</label><input id="mEnd" readonly value="${esc(a.end_jalali||'')}" data-greg="${esc(a.end_date_gregorian||jalaliInputToGreg(a.end_jalali||''))}" onclick="openDatePicker('mEnd')"><div id="mEndPreview" class="selected-date small">پایان بازه و بایگانی خودکار</div></div><div class="field"><label>ساعت</label><input id="mTime" value="${esc(a.event_time||'')}"></div><div class="field"><label>مکان</label><input id="mLocation" value="${esc(a.location||'')}"></div><div class="field"><label>پوستر</label><input id="mPoster" type="file" accept="image/*"></div>${tagInput(a.tags||[])}<div class="field full"><label>متن اعلان</label><textarea id="mBody">${esc(a.body||'')}</textarea></div></div><div class="actions"><button class="btn" onclick="closeModal()">انصراف</button><button class="btn primary" onclick="saveAnnouncement(${id})">ذخیره</button></div>`)}
async function saveAnnouncement(id){try{let poster='';if($('mPoster').files[0])poster=await uploadFile('poster',$('mPoster').files[0]);await api('announcements.php',{method:id?'PUT':'POST',body:JSON.stringify({id,title:$('mTitle').value,category_id:$('mCat').value,event_date:$('mStart').value,hijri_date:$('mStart').dataset.hijri||'',start_gregorian:$('mStart').dataset.greg||'',end_gregorian:$('mEnd').dataset.greg||'',start_jalali:$('mStart').value,end_jalali:$('mEnd').value,event_time:$('mTime').value,location:$('mLocation').value,poster_url:poster,body:$('mBody').value,tags:$('mTags').value})});closeModal();await load();toast('اعلان ذخیره شد.')}catch(e){toast(e.message)}}
