function openCollectionEdit(id=0){const c=state.collections.find(x=>Number(x.id)===Number(id))||{};modal(`<div class="modalhead"><h2>مجموعه</h2><button class="close" onclick="closeModal()">✕</button></div><div class="formgrid"><div class="field"><label>عنوان</label><input id="cTitle" value="${esc(c.title||'')}"></div><div class="field"><label>نوع جلسه</label><select id="cCat">${catOptions('audio',c.category_id)}</select></div><div class="field"><label>تعداد کل جلسات</label><input id="cCount" type="number" min="1" value="${esc(c.session_count||'')}"></div><div class="field"><label>پوستر مجموعه</label><input id="cPoster" type="file" accept="image/*"></div><div class="field"><label>شروع بازه</label><input id="cStart" readonly value="${esc(c.start_jalali||'')}" data-greg="${esc(c.start_date_gregorian||'')}" onclick="openDatePicker('cStart')"></div><div class="field"><label>پایان بازه</label><input id="cEnd" readonly value="${esc(c.end_jalali||'')}" data-greg="${esc(c.end_date_gregorian||'')}" onclick="openDatePicker('cEnd')"></div>${tagInput(c.tags||[])}<div class="field full"><label>توضیح</label><textarea id="cDesc">${esc(c.description||'')}</textarea></div></div><div class="actions"><button class="btn primary" onclick="saveCollectionEdit(${id})">ذخیره</button></div>`)}
