function openCategories(){modal(`<div class="modalhead"><h2>دسته‌بندی‌ها</h2><button class="close" onclick="closeModal()">✕</button></div><div class="formgrid"><div class="field"><label>نام</label><input id="cName"></div><div class="field"><label>نوع</label><select id="cKind"><option value="all">همه</option><option value="audio">صوتی</option><option value="article">مطلب</option><option value="announcement">اعلان</option><option value="collection">مجموعه</option></select></div></div><div class="actions"><button class="btn primary" onclick="saveCategory()">افزودن</button></div><div style="margin-top:15px">${state.categories.map(c=>`<div class="fish-card"><b>${esc(c.name)}</b> <span class="small">${esc(c.kind)}</span><button class="btn danger" style="float:left" onclick="del('categories.php',${c.id})">حذف</button></div>`).join('')}</div>`)}
