async function del(path,id){if(!confirm('آیا از حذف این مورد مطمئن هستید؟'))return;try{await api(path,{method:'DELETE',body:JSON.stringify({id})});await load();toast('حذف انجام شد.')}catch(e){toast(e.message)}}
// Persian/Jalali calendar
const months=['فروردین','اردیبهشت','خرداد','تیر','مرداد','شهریور','مهر','آبان','آذر','دی','بهمن','اسفند'];
function g2j(gy,gm,gd){const gdm=[0,31,59,90,120,151,181,212,243,273,304,334],gy2=gm>2?gy+1:gy;let days=355666+365*gy+Math.floor((gy2+3)/4)-Math.floor((gy2+99)/100)+Math.floor((gy2+399)/400)+gd+gdm[gm-1];let jy=-1595+33*Math.floor(days/12053);days%=12053;jy+=4*Math.floor(days/1461);days%=1461;if(days>365){jy+=Math.floor((days-1)/365);days=(days-1)%365}let jm=days<186?1+Math.floor(days/31):7+Math.floor((days-186)/30);let jd=1+(days<186?days%31:(days-186)%30);return[jy,jm,jd]}
function j2g(jy,jm,jd){jy+=1595;let days=-355668+365*jy+Math.floor(jy/33)*8+Math.floor((jy%33+3)/4)+jd+(jm<7?(jm-1)*31:(jm-7)*30+186);let gy=400*Math.floor(days/146097);days%=146097;if(days>36524){gy+=100*Math.floor(--days/36524);days%=36524;if(days>=365)days++}gy+=4*Math.floor(days/1461);days%=1461;if(days>365){gy+=Math.floor((days-1)/365);days=(days-1)%365}let gd=days+1,gm=0;const md=[31,(gy%4===0&&gy%100!==0)||gy%400===0?29:28,31,30,31,30,31,31,30,31,30,31];while(gm<12&&gd>md[gm]){gd-=md[gm];gm++}return[gy,gm+1,gd]}
function gregDateStr(a){return a.map((x,i)=>String(x).padStart(i===1||i===2?2:4,'0')).join('-')}
function islamicFromGregorian(gy,gm,gd){const jd=Math.floor((1461*(gy+4800+Math.floor((gm-14)/12)))/4)+Math.floor((367*(gm-2-12*Math.floor((gm-14)/12)))/12)-Math.floor((3*Math.floor((gy+4900+Math.floor((gm-14)/12))/100))/4)+gd-32075;let l=jd-1948440+10632;let n=Math.floor((l-1)/10631);l=l-10631*n+354;let j=(Math.floor((10985-l)/5316))*Math.floor((50*l)/17719)+(Math.floor(l/5670))*Math.floor((43*l)/15238);l=l-(Math.floor((30-j)/15))*Math.floor((17719*j)/50)-(Math.floor(j/16))*Math.floor((15238*j)/43)+29;let m=Math.floor((24*l)/709);let d=l-Math.floor((709*m)/24);let y=30*n+j-30;return[y,m,d]}
const hijriMonths=['محرم','صفر','ربیع‌الاول','ربیع‌الثانی','جمادی‌الاول','جمادی‌الثانی','رجب','شعبان','رمضان','شوال','ذی‌القعده','ذی‌الحجه'];
function islamicDateParts(gy,gm,gd){try{const parts=new Intl.DateTimeFormat('en-u-ca-islamic-umalqura-nu-latn',{day:'numeric',month:'numeric',year:'numeric',timeZone:'UTC'}).formatToParts(new Date(Date.UTC(gy,gm-1,gd)));const values=Object.fromEntries(parts.filter(part=>part.type!=='literal').map(part=>[part.type,Number(part.value)]));if(values.year&&values.month&&values.day)return[values.year,values.month,values.day]}catch(error){}return islamicFromGregorian(gy,gm,gd)}
function formatHijri(gy,gm,gd){const [year,month,day]=islamicDateParts(gy,gm,gd);return `${faNum(day)} ${hijriMonths[month-1]||faNum(month)} ${faNum(year)}`}
function sessionHijri(lecture){return hijriLabel(lecture.hijri_date||'')}
function validCalendarDate(year,month,day){return Number.isInteger(year)&&month>=1&&month<=12&&day>=1&&day<=31}
function hijriLabel(value){const text=String(value||'').trim();const ascii=text.replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d));const parts=ascii.match(/\d+/g);if(parts?.length===3){const [year,month,day]=parts.map(Number);if(year>1000&&month>=1&&month<=12&&day>=1&&day<=30)return `${faNum(day)} ${hijriMonths[month-1]} ${faNum(year)}`}return text}
function faNum(s){return String(s).replace(/\d/g,d=>'۰۱۲۳۴۵۶۷۸۹'[d])}
function jalaliInputToGreg(v){const z=String(v||'').replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[^0-9]+/g,'/').split('/').filter(Boolean).map(Number);if(z.length!==3)return '';const g=j2g(z[0],z[1],z[2]);return gregDateStr(g)}
function openDatePicker(inputId){dateTarget=inputId;const el=$(inputId);let jy,jm,jd;if(el.dataset.greg){const p=el.dataset.greg.split('-').map(Number);[jy,jm,jd]=g2j(p[0],p[1],p[2])}else{const now=new Date();[jy,jm,jd]=g2j(now.getFullYear(),now.getMonth()+1,now.getDate())}renderCalendar(jy,jm,jd)}
function renderCalendar(y,m,d){const today=new Date(),currentYear=g2j(today.getFullYear(),today.getMonth()+1,today.getDate())[0],maxYear=Math.max(currentYear+1,y),years=Array.from({length:maxYear-1379},(_,index)=>maxYear-index).filter(year=>year>=1380);const days=Array.from({length:31},(_,i)=>i+1);$('calbox').innerHTML=`<div class="modalhead"><h2>انتخاب تاریخ شمسی</h2><button class="close" onclick="closeCalendar()">✕</button></div><div class="calhint">سه انتخابگر اسکرولی برای روز، ماه و سال</div><div class="wheel-wrap"><div class="wheel" id="wd">${days.map(x=>`<button class="${x===d?'active':''}" onclick="selectWheel('d',${x})">${faNum(x)}</button>`).join('')}</div><div class="wheel" id="wm">${months.map((x,i)=>`<button class="${i+1===m?'active':''}" onclick="selectWheel('m',${i+1})">${x}</button>`).join('')}</div><div class="wheel" id="wy">${years.map(x=>`<button class="${x===y?'active':''}" onclick="selectWheel('y',${x})">${faNum(x)}</button>`).join('')}</div></div><div class="selected-date" id="calSelected"></div><div class="actions" style="justify-content:center"><button class="btn" onclick="closeCalendar()">انصراف</button><button class="btn primary" onclick="confirmCalendar()">تأیید تاریخ</button></div>`;$('calendar').dataset.y=y;$('calendar').dataset.m=m;$('calendar').dataset.d=d;$('calendar').classList.add('show');updateCalText()}
function selectWheel(k,v){if(k==='y')$('calendar').dataset.y=v;if(k==='m')$('calendar').dataset.m=v;if(k==='d')$('calendar').dataset.d=v;updateCalText()}
function updateCalText(){const y=Number($('calendar').dataset.y),m=Number($('calendar').dataset.m),d=Math.min(Number($('calendar').dataset.d),m<=6?31:(m===12?30:30));$('calendar').dataset.d=d;const g=j2g(y,m,d);$('calSelected').innerHTML=`<b>${faNum(y)}/${faNum(String(m).padStart(2,'0'))}/${faNum(String(d).padStart(2,'0'))}</b><br>معادل میلادی: ${gregDateStr(g)} · قمری: ${formatHijri(g[0],g[1],g[2])}`}
function confirmCalendar(){const y=Number($('calendar').dataset.y),m=Number($('calendar').dataset.m),d=Number($('calendar').dataset.d),g=j2g(y,m,d),el=$(dateTarget);el.value=`${faNum(y)}/${faNum(String(m).padStart(2,'0'))}/${faNum(String(d).padStart(2,'0'))}`;el.dataset.greg=gregDateStr(g);el.dataset.hijri=formatHijri(g[0],g[1],g[2]);if($(dateTarget+'Preview'))$(dateTarget+'Preview').textContent='تاریخ قمری: '+el.dataset.hijri;closeCalendar()}
function closeCalendar(){$('calendar').classList.remove('show')}$('calendar').addEventListener('click',e=>{if(e.target.id==='calendar')closeCalendar()});
function formatTime(s){s=Number(s)||0;return Math.floor(s/60).toString().padStart(2,'0')+':'+(s%60).toString().padStart(2,'0')}
function openLightbox(i){lightIndex=i;const x=lightItems[i];if(!x)return;$('lightImg').src=x.url;$('lightCaption').textContent=x.caption||x.lecture_title||'';$('lightbox').classList.add('show')}function closeLightbox(){$('lightbox').classList.remove('show')}function lightPrev(){lightIndex=(lightIndex-1+lightItems.length)%lightItems.length;openLightbox(lightIndex)}function lightNext(){lightIndex=(lightIndex+1)%lightItems.length;openLightbox(lightIndex)}$('lightbox').addEventListener('click',e=>{if(e.target.id==='lightbox')closeLightbox()});
function openLecture(id=0,existingCollection=0){const lecture=state.lectures.find(item=>Number(item.id)===Number(id))||{};const collectionId=existingCollection||lecture.collection_id||0;const collection=state.collections.find(item=>Number(item.id)===Number(collectionId))||{};const isEdit=!!id;window.lectureAppendMode=!!collectionId;const title=collection.title||lecture.collection_title||lecture.title||'';const numberValue=lecture.session_number||'';const countValue=collection.session_count||lecture.session_count||'';const sharedFields=collectionId?'':`<div class="field"><label>عنوان</label><input id="mTitle" value="${esc(lecture.title||'')}" placeholder="عنوان جلسه یا مجموعه"></div><div class="field"><label>نوع جلسه</label><select id="mCat">${catOptions('audio',lecture.category_id)}</select></div>`;const modeControl=collectionId?'':`<div class="field"><label>نوع بارگذاری</label><div class="actions"><label><input type="radio" name="mode" value="single" checked onchange="toggleLectureMode()"> تک جلسه</label><label><input type="radio" name="mode" value="collection" onchange="toggleLectureMode()"> مجموعه جلسات</label></div></div>`;const numberField=`<div class="field ${collectionId?'':'hidden'}" id="sessionNumberField"><label>شماره جلسه</label><input id="mNum" type="number" min="1" value="${esc(numberValue)}" placeholder="مثلاً ۱"></div>`;const rangeFields=collectionId?'':`<div id="collectionFields" class="field full hidden"><div class="formgrid"><div class="field"><label>شروع بازه</label><input id="mStart" readonly value="" onclick="openDatePicker('mStart')" placeholder="انتخاب تاریخ"></div><div class="field"><label>پایان بازه</label><input id="mEnd" readonly value="" onclick="openDatePicker('mEnd')" placeholder="انتخاب تاریخ"></div><div class="field" id="sessionCountField"><label>تعداد کل جلسات</label><input id="mCount" type="number" min="1" value="" placeholder="مثلاً ۱۰"></div></div></div>`;const heading=collectionId?(isEdit?'ویرایش جلسه مجموعه':`افزودن جلسه به ${esc(title)}`):(isEdit?'ویرایش جلسه':'ثبت جلسه صوتی');modal(`<div class="modalhead"><h2>${heading}</h2><button class="close" onclick="closeModal()">✕</button></div>${modeControl}<div class="formgrid">${sharedFields}<div class="field"><label>تاریخ شمسی</label><input id="mDate" readonly value="${esc(lecture.session_date||'')}" data-greg="${esc(lecture.session_date_gregorian||'')}" data-hijri="${esc(lecture.hijri_date||'')}" onclick="openDatePicker('mDate')" placeholder="انتخاب تاریخ"><div id="mDatePreview" class="selected-date small">${lecture.hijri_date?`تاریخ قمری: ${esc(lecture.hijri_date)}`:'برای انتخاب تاریخ کلیک کنید'}</div></div><div class="field"><label>فایل صوتی ${isEdit?'(در صورت تغییر انتخاب کنید)':''}</label><input id="mAudio" type="file" accept="audio/*"></div>${numberField}${rangeFields}${tagInput(lecture.tags||[])}<div class="field full"><label>توضیحات</label><textarea id="mDesc">${esc(lecture.description||'')}</textarea></div><div class="field full"><label>آلبوم عکس جلسه ${isEdit?'(تصاویر جدید را اضافه کنید)':''}</label><input id="mPhotos" type="file" accept="image/*" multiple><div class="small">چند عکس را همزمان انتخاب کنید؛ تصاویر قبلی حذف نمی‌شوند.</div></div></div><div class="actions"><button class="btn" onclick="closeModal()">انصراف</button><button class="btn primary" onclick="saveLecture(${id},${collectionId})">ذخیره جلسه</button></div>`);toggleLectureMode()}
function toggleLectureMode(){const mode=window.lectureAppendMode?'collection':(document.querySelector('input[name="mode"]:checked')?.value||'single');$('collectionFields')?.classList.toggle('hidden',mode!=='collection');$('sessionNumberField')?.classList.toggle('hidden',mode!=='collection');$('sessionCountField')?.classList.toggle('hidden',mode!=='collection')}
async function saveLecture(id,oldCollectionId){try{const isAppending=!!oldCollectionId;const mode=isAppending?'collection':(document.querySelector('input[name="mode"]:checked')?.value||'single');const existing=state.lectures.find(item=>Number(item.id)===Number(id))||{};const collection=state.collections.find(item=>Number(item.id)===Number(oldCollectionId))||{};const title=isAppending?(collection.title||existing.collection_title||existing.title):$('mTitle').value.trim();const categoryId=isAppending?(collection.category_id||existing.category_id):$('mCat').value;const sessionNumber=mode==='collection'?Number($('mNum').value||0):0;const sessionCount=isAppending?(collection.session_count||existing.session_count||0):(mode==='collection'?Number($('mCount').value||0):0);if(!title)throw new Error('عنوان جلسه الزامی است.');if(!$('mDate').value)throw new Error('تاریخ جلسه را انتخاب کنید.');if(!id&&!$('mAudio').files[0])throw new Error('فایل صوتی را انتخاب کنید.');if(mode==='collection'&&(!sessionNumber||!sessionCount&& !isAppending))throw new Error('شماره و تعداد کل جلسات را وارد کنید.');if(mode==='collection'&&!isAppending&&(!$('mStart').dataset.greg||!$('mEnd').dataset.greg))throw new Error('بازه تاریخ مجموعه را کامل کنید.');if(mode==='collection'&&!isAppending&&Number(sessionNumber)>Number(sessionCount))throw new Error('شماره جلسه از تعداد کل جلسات بیشتر است.');let audio='';if($('mAudio').files[0])audio=await uploadFile('audio',$('mAudio').files[0]);let collectionId=oldCollectionId||0;if(mode==='collection'&&!collectionId){const created=await api('collections.php',{method:'POST',body:JSON.stringify({title,category_id:categoryId,session_count:sessionCount,description:'',start_gregorian:$('mStart').dataset.greg,end_gregorian:$('mEnd').dataset.greg,start_jalali:$('mStart').value,end_jalali:$('mEnd').value,tags:[]})});collectionId=created.id}const payload={id,title,category_id:categoryId,date:$('mDate').value,date_gregorian:$('mDate').dataset.greg||'',hijri_date:$('mDate').dataset.hijri||'',description:$('mDesc').value,audio_url:audio,collection_id:collectionId,session_number:sessionNumber||null,session_count:sessionCount||null,tags:$('mTags').value};const saved=await api('lectures.php',{method:id?'PUT':'POST',body:JSON.stringify(payload)});const savedId=id||saved.id;const photos=[...$('mPhotos').files];for(let index=0;index<photos.length;index++){const url=await uploadFile('gallery',photos[index]);await api('gallery.php',{method:'POST',body:JSON.stringify({lecture_id:savedId,url,caption:'',sort_order:index})})}closeModal();await load();toast('جلسه با موفقیت ذخیره شد.')}catch(error){toast(error.message)}}
</script><link rel="stylesheet" href="assets/enhancements.css"><script src="assets/enhancements.js"></script></body></html>
